head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30013";
scwin.grd_List_Tab1 = null;
scwin.btn_Save = null;
scwin.btn_Close = null;
scwin.index = '1';
scwin.winHight = undefined;
scwin.dts_Grid_Tab1 = null;
scwin.dts_Grid_Tab2 = null;
scwin.gDepCd = undefined;
scwin.gEmpNo = undefined;
scwin.gLdMktTp = undefined;
scwin.gJobTitl = undefined;
scwin.gDuty = undefined;
scwin.fn_Search = null;
scwin.fn_Save = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    if (js_duty_chrg === 'Y') {
        scwin.gDuty = 'Y';
    }
    if ((js_duty === "Y" || js_duty_chrg === "Y") || (scwin.gJobTitl === '06' || scwin.gJobTitl === '09')) {
        scwin.winHight = '620';
    } else {
        scwin.winHight = '620';
        scwin.btn_Close.hide();
        scwin.btn_Save.hide();
    }
    scwin.fn_Search('1');
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        MxTab_1.activeindex = "1";
        scwin.init();
        scwin.resizeToWin();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.gDepCd =$c.session.getUserInfo("depCd"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

try { scwin.gEmpNo =$c.session.getUserInfo("empNo"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

try { scwin.gLdMktTp =$c.session.getUserInfo("market"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

try { scwin.gJobTitl =js_jobtitl; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

try { scwin.gDuty =js_duty; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.grd_List_Tab1 = $c.util.getComponent('grd_List_Tab1');
        scwin.btn_Save = $c.util.getComponent('btn_Save');
        scwin.btn_Close = $c.util.getComponent('btn_Close');
        scwin.dts_Grid_Tab1 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Grid_Tab1')) : $c.util.getComponent('dts_Grid_Tab1');
        scwin.dts_Grid_Tab2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Grid_Tab2')) : $c.util.getComponent('dts_Grid_Tab2');
        scwin.fn_Search = scwin.tx_script_dts_Grid_Tab1;
        scwin.fn_Save = scwin.sbm_trs_Save;
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf30013.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @event
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
 */
// TODO Stage2: 중복 정의 — as-is 에서 뒤 정의에 덮여 호출되지 않던 본문(JS 는 마지막 정의가 이긴다). 필요 없으면 삭제 — 원이름 btn_Excel_onclick

/**
 * @method
 * @name btn_Excel_onclick_1
 * @description btn Excel onclick 1 처리
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick_1 = function () {
    try {
        /* TODO Stage2: 접속 로그 저장 보류(공급사 doLogSave — 운영 필요 여부 회신 ㉤ 뒤 결정) $c.fil.doLogSave(scwin.vScrenID, $c.fil.SCREN_PROCS_TP_CD_07); */
        grd_Grid.GridToExcel("일정검색", "", "2");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.btn_Excel_onclick' }); }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function () {
    try {
        /* TODO Stage2: 접속 로그 저장 보류(공급사 doLogSave — 운영 필요 여부 회신 ㉤ 뒤 결정) $c.fil.doLogSave(scwin.vScrenID, $c.fil.SCREN_PROCS_TP_CD_07); */
        scwin.grd_List_Tab1.GridToExcel("일정확인", "", "2");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.btn_Excel_onclick' }); }
};

/**
 * @method
 * @name dts_Grid_Tab1_onloadcompleted
 * @description dts_Grid_Tab1 onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_Tab1_onloadcompleted = function (rowcount) {
    try {
        void 0;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30013.dts_Grid_Tab1_onloadcompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab1_onloaderror
 * @description dts_Grid_Tab1 onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_Tab1_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_Grid_Tab1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30013.dts_Grid_Tab1_onloaderror" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab2_onloadcompleted
 * @description dts_Grid_Tab2 onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_Tab2_onloadcompleted = function (rowcount) {
    try {
        void 0;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30013.dts_Grid_Tab2_onloadcompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab2_onloaderror
 * @description dts_Grid_Tab2 onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_Tab2_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_Grid_Tab2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30013.dts_Grid_Tab2_onloaderror" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description btn_Save 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Save_onclick = function () {
    try {
        scwin.fn_Save();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.btn_Save_onclick' }); }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.btn_Close_onclick' }); }
};

/**
 * @method
 * @name MxTab_1_onselchanged
 * @description MxTab_1 onselchanged 이벤트
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MxTab_1_onselchanged = function (nIndex) {
    try {
        if (nIndex === 1) {
            scwin.fn_Search('1');
        } else {
            if (nIndex === 2) {
                scwin.fn_Search('2');
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.MxTab_1_onselchanged' }); }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        scwin.fn_Search(scwin.index);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf30013.trs_Save_onsuccess" });
    }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description 알림을 띄운다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onfail = async function () {
    try {
        await $c.win.alert('trs_Save.OnFail() :' + trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf30013.trs_Save_onfail" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_Grid_Tab1
 * @description script dts Grid Tab1 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_Grid_Tab1 = async function () {
    $c.util.getComponent("dma_scriptDts_Grid_Tab1Req").set("DUTY_YN", "Y");
    $c.util.getComponent("dma_scriptDts_Grid_Tab1Req").set("DUTY_YN", "N");
    $c.util.getComponent("dma_scriptDts_Grid_Tab1Req").set("SCREN_ID", 'ULDSTF30013.gfm');
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — LD_MKT_TP_CD, DEP_CD, EMP_NO, JOB_TITL, GUBUN, SCREN_PROCES_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — LD_MKT_TP_CD, DEP_CD, EMP_NO, JOB_TITL, GUBUN, SCREN_PROCES_TP_CD", unresolved: "query_param:LD_MKT_TP_CD,DEP_CD,EMP_NO,JOB_TITL,GUBUN,SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_Grid_Tab1",
        method: "post",
        action: "/DisclosureSchedule.do",
        ref: "dma_scriptDts_Grid_Tab1Req",
        target: "dts_Grid_Tab1=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_Grid_Tab1_onloaderror'] === 'function') ? scwin['dts_Grid_Tab1_onloaderror'] : (typeof scwin['dts_Grid_Tab1_onfail'] === 'function') ? scwin['dts_Grid_Tab1_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_Grid_Tab1_onloadcompleted'] === 'function') ? scwin['dts_Grid_Tab1_onloadcompleted'] : ((typeof scwin['dts_Grid_Tab1_onsuccess'] === 'function') ? scwin['dts_Grid_Tab1_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_Grid_Tab1'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30013.tx_script_dts_Grid_Tab1" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name sbm_trs_Save
 * @description trs Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_trs_Save = async function () {
    const sbmOptions = {
        id: "sbm_trs_Save",
        method: "post",
        action: "/DisclosureSchedule.do",
        ref: "dma_sbmTrs_SaveReq",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['trs_Save_onloaderror'] === 'function') ? scwin['trs_Save_onloaderror'] : (typeof scwin['trs_Save_onfail'] === 'function') ? scwin['trs_Save_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Save_onloadcompleted'] === 'function') ? scwin['trs_Save_onloadcompleted'] : ((typeof scwin['trs_Save_onsuccess'] === 'function') ? scwin['trs_Save_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Save'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30013.sbm_trs_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Height, $c.frame.Width
    $c.frame.Width = 635;
    $c.frame.Height = scwin.winHight;
};

/**
 * @method
 * @name searchMain
 * @description search Main 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchMain = function () {
    if (MxTab_1.selectedIndex === 1) {
        scwin.fn_Search('1');
    } else {
        if (MxTab_1.selectedIndex === 2) {
            scwin.fn_Search('2');
        }
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
